// First-run setup: creates .env.local with secure random secrets if it doesn't exist yet.
// Usage: npm run setup
import fs from "node:fs";
import crypto from "node:crypto";

const path = ".env.local";
if (fs.existsSync(path)) {
  console.log(".env.local already exists. Nothing changed.");
  process.exit(0);
}
const password = crypto.randomBytes(12).toString("base64url");
const env = `# ── Simply Being Female platform ──────────────────────────────
# Generated by npm run setup. Keep this file private; it is git-ignored.

# Owner login (change the password after first sign-in by editing here and restarting)
SBF_OWNER_EMAIL=owner@simplybeingfemale.local
SBF_OWNER_PASSWORD=${password}
SBF_OWNER_NAME=SBF owner

# Encrypts social account tokens at rest (32 bytes, base64). Never change once accounts are connected.
ENCRYPTION_KEY=${crypto.randomBytes(32).toString("base64")}

# AI (research, briefs, content, design feedback). Without it the platform runs in clearly-labelled demo mode.
ANTHROPIC_API_KEY=
# SBF_AI_MODEL=claude-opus-5-5

# Database. Leave empty for the built-in local PostgreSQL (stored in .data/pg).
DATABASE_URL=

# URLs
APP_URL=http://localhost:3000
# Public HTTPS address networks use to fetch approved images (required for Instagram/Pinterest/Threads).
PUBLIC_BASE_URL=

# Social network developer apps (add when approved)
META_APP_ID=
META_APP_SECRET=
THREADS_APP_ID=
THREADS_APP_SECRET=
TIKTOK_CLIENT_KEY=
TIKTOK_CLIENT_SECRET=
LINKEDIN_CLIENT_ID=
LINKEDIN_CLIENT_SECRET=
LINKEDIN_ORGANIZATION_URN=
PINTEREST_APP_ID=
PINTEREST_APP_SECRET=
PINTEREST_BOARD_ID=
GOOGLE_CLIENT_ID=
GOOGLE_CLIENT_SECRET=
X_CLIENT_ID=
X_CLIENT_SECRET=

# Protects /api/cron/* when using an external scheduler
CRON_SECRET=${crypto.randomBytes(24).toString("base64url")}
`;
fs.writeFileSync(path, env);
console.log("Created .env.local. Your owner login email and password are in that file.");
